{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울 택시 기사가 시 운영 공영 노외주차장에서 화장실 이용 목적으로 35분 주차한 경우 주차비 무료 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제15호다목에 따르면, 「여객자동차 운수사업법」 제3조제1항제2호에 따른 서울시 택시운송사업 차량 중 운수종사자의 화장실 이용을 목적으로 시장이 설치 또는 관리하는 공영 노외주차장에 입차한 자동차는 입·출차 기준 30분 이내인 경우에 한하여 주차요금을 면제한다. 질문의 35분은 이 30분 이내 요건을 충족하지 못하므로, 해당 면제 규정을 적용받지 못한다.",
          "b_ids": "주차장:제7조제1항제15호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
